use std::{env,fs,io::{Read,Write},os::unix::net::UnixStream,path::PathBuf,process::{Child,Command,Stdio},thread,time::{Duration,Instant}};

fn arg(args:&[String],name:&str,default:Option<&str>)->Result<String,String>{match args.iter().position(|x|x==name){Some(i)=>args.get(i+1).cloned().ok_or_else(||format!("{name} requires a value")),None=>default.map(str::to_owned).ok_or_else(||format!("missing {name}"))}}
fn tail(path:&PathBuf,n:usize)->String{fs::read_to_string(path).map(|s|s.lines().rev().take(n).collect::<Vec<_>>().into_iter().rev().collect::<Vec<_>>().join("\n")).unwrap_or_else(|_|"<serial log not created>".into())}
fn wait_serial(path:&PathBuf,marker:&str,child:&mut Child,timeout:Duration)->Result<(),String>{let end=Instant::now()+timeout;while Instant::now()<end{if let Ok(s)=fs::read_to_string(path){if s.contains(marker){return Ok(())}}if let Some(status)=child.try_wait().map_err(|e|e.to_string())?{return Err(format!("QEMU exited with {status} before serial marker {marker:?}\n{}",tail(path,80)))}thread::sleep(Duration::from_millis(100));}Err(format!("timed out waiting for serial marker {marker:?}\n{}",tail(path,80)))}
fn connect_monitor(path:&PathBuf,child:&mut Child)->Result<UnixStream,String>{let end=Instant::now()+Duration::from_secs(10);loop{match UnixStream::connect(path){Ok(s)=>{s.set_read_timeout(Some(Duration::from_millis(500))).map_err(|e|e.to_string())?;return Ok(s)},Err(e)=>{if let Some(status)=child.try_wait().map_err(|x|x.to_string())?{return Err(format!("QEMU exited with {status} before monitor socket: {e}"))}if Instant::now()>=end{return Err(format!("QEMU monitor socket unavailable {}: {e}",path.display()))}thread::sleep(Duration::from_millis(100));}}}}
fn read_prompt(s:&mut UnixStream)->Result<(),String>{let end=Instant::now()+Duration::from_secs(3);let mut data=Vec::new();let mut buf=[0u8;4096];while Instant::now()<end&&!data.windows(6).any(|w|w==b"(qemu)"){match s.read(&mut buf){Ok(0)=>break,Ok(n)=>data.extend_from_slice(&buf[..n]),Err(e) if e.kind()==std::io::ErrorKind::WouldBlock||e.kind()==std::io::ErrorKind::TimedOut=>{},Err(e)=>return Err(e.to_string())}}if data.windows(6).any(|w|w==b"(qemu)"){Ok(())}else{Err(format!("QEMU HMP prompt missing: {:?}",String::from_utf8_lossy(&data)))}}
pub fn run(args:&[String])->Result<(),String>{
 let qemu=arg(args,"--qemu",Some("qemu-system-x86_64"))?;let code=PathBuf::from(arg(args,"--code",None)?);let vars=PathBuf::from(arg(args,"--vars-template",None)?);let disk=PathBuf::from(arg(args,"--disk",None)?);let page=PathBuf::from(arg(args,"--pagefile",None)?);let serial=PathBuf::from(arg(args,"--serial",None)?);let monitor=PathBuf::from(arg(args,"--monitor",None)?);let debug=PathBuf::from(arg(args,"--debug-log",None)?);
 let memory=arg(args,"--memory",Some("5G"))?;let smp=arg(args,"--smp",Some("2"))?;let boot=arg(args,"--boot-timeout",Some("60"))?.parse::<u64>().map_err(|e|e.to_string())?;let input=arg(args,"--input-timeout",Some("10"))?.parse::<u64>().map_err(|e|e.to_string())?;
 for p in [&code,&vars,&disk,&page]{if !p.is_file(){return Err(format!("required QEMU input missing: {}",p.display()))}}
 for p in [&serial,&monitor,&debug]{if let Some(parent)=p.parent(){fs::create_dir_all(parent).map_err(|e|e.to_string())?}}
 fs::write(&serial,[]).map_err(|e|e.to_string())?;fs::write(&debug,[]).map_err(|e|e.to_string())?;let _=fs::remove_file(&monitor);
 let vars_path=serial.parent().unwrap_or_else(||std::path::Path::new(".")).join("OVMF_VARS_ps2.fd");fs::copy(&vars,&vars_path).map_err(|e|e.to_string())?;
 let launch=debug.with_extension("launch.log");let out=fs::File::create(launch).map_err(|e|e.to_string())?;
 let mut child=Command::new(qemu).args(["-machine","q35","-m",&memory,"-cpu","max","-smp",&smp,"-device","intel-iommu,intremap=off,caching-mode=on,aw-bits=48","-device","qemu-xhci,id=xhci","-device","piix3-ide,id=legacyide,bus=pcie.0"])
 .args(["-drive",&format!("if=pflash,format=raw,readonly=on,file={}",code.display()),"-drive",&format!("if=pflash,format=raw,file={}",vars_path.display()),"-drive",&format!("if=none,id=osdisk,format=raw,file={}",disk.display()),"-device","ide-hd,drive=osdisk,bus=legacyide.0,unit=0","-drive",&format!("if=none,id=pagefile,format=raw,file={}",page.display()),"-device","ide-hd,drive=pagefile,bus=legacyide.0,unit=1","-boot","order=c","-display","none","-monitor",&format!("unix:{},server=on,wait=off",monitor.display()),"-serial",&format!("file:{}",serial.display()),"-d","int,cpu_reset,guest_errors","-D",&debug.display(),"-no-reboot","-no-shutdown"]).stdout(Stdio::from(out.try_clone().map_err(|e|e.to_string())?)).stderr(Stdio::from(out)).spawn().map_err(|e|format!("failed to start QEMU: {e}"))?;
 let result=(||{wait_serial(&serial,"PS/2 IRQ: route enabled after controller initialization; bounded ISR active.",&mut child,Duration::from_secs(boot))?;let mut mon=connect_monitor(&monitor,&mut child)?;read_prompt(&mut mon)?;for key in ["a","shift-a","ret"]{writeln!(mon,"sendkey {key}").map_err(|e|e.to_string())?;read_prompt(&mut mon)?;thread::sleep(Duration::from_millis(150));}wait_serial(&serial,"QEMU KEYBOARD INPUT:",&mut child,Duration::from_secs(input))?;let _=writeln!(mon,"quit");println!("PS/2 keyboard smoke passed: monitor-injected keys reached IRQ1 and KbdClass.");Ok(())})();
 if child.try_wait().ok().flatten().is_none(){let _=child.kill();}let _=child.wait();result
}
